        return value, None, 0

    def _store_error(self, operation: str, exc: BaseException) -> None:
        print(f"{operation} failed: {exc}", file=sys.stderr)
        self._error(500, "persistence failure")

    def do_GET(self) -> None:
        path = self._path()
        try:
            if path == "/health":
