    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever(poll_interval=0.1)
    finally:
        server.server_close()
        try:
            store.compact()
        except OSError as exc:
            print(f"shutdown persistence failed: {exc}", file=sys.stderr)
            return 1
    return 0


