        path = self._path()
        try:
            if path == "/health":
                self._send_json(200, {"status": "ok"})
                return
            if path == "/v1/keys":
                self._send_json(200, {"keys": self.server.store.keys()})
                return
            key, error = self._key()
            if error is not None:
                self._error(400, error)
                return
            if key is not None:
                found, value = self.server.store.get(key)
                if found:
