import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024


class Store:
    """Thread-safe store with synchronous, atomic persistence."""

    def __init__(self, path: Path) -> None:
        self.path = path
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, Any]] = {}
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            return
        with self.path.open("r", encoding="utf-8") as stream:
            document = json.load(stream, parse_constant=self._reject_constant)
        if not isinstance(document, dict) or not isinstance(document.get("entries"), dict):
            raise ValueError("data file has an invalid format")

        loaded: dict[str, dict[str, Any]] = {}
        for key, entry in document["entries"].items():
            if not isinstance(key, str) or not isinstance(entry, dict):
                raise ValueError("data file has an invalid entry")
            if set(entry) != {"value", "expires_at"}:
                raise ValueError("data file has an invalid entry")
            expires_at = entry["expires_at"]
            if expires_at is not None and (
                isinstance(expires_at, bool)
                or not isinstance(expires_at, (int, float))
                or not math.isfinite(expires_at)
            ):
                raise ValueError("data file has an invalid expiry")
            loaded[key] = {"value": entry["value"], "expires_at": expires_at}

        self.entries = loaded
        if self._prune_locked():
            self._persist_locked()

    @staticmethod
    def _reject_constant(value: str) -> None:
        raise ValueError(f"non-finite JSON number: {value}")

    def _prune_locked(self) -> bool:
        now = time.time()
        expired = [
            key
            for key, entry in self.entries.items()
            if entry["expires_at"] is not None and entry["expires_at"] <= now
        ]
        for key in expired:
            del self.entries[key]
        return bool(expired)

    def _persist_locked(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, temporary_name = tempfile.mkstemp(
            prefix=f".{self.path.name}.", suffix=".tmp", dir=self.path.parent
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(
                    {"entries": self.entries},
                    stream,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    allow_nan=False,
                )
                stream.write("\n")
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary_name, self.path)
            try:
                directory_fd = os.open(self.path.parent, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                # Directory fsync is not available on every supported filesystem.
                pass
        except BaseException:
            try:
                os.unlink(temporary_name)
            except FileNotFoundError:
                pass
            raise

    def put(self, key: str, value: Any, ttl: float | None) -> bool:
        with self.lock:
            old_entries = self.entries.copy()
            self._prune_locked()
            created = key not in self.entries
            expires_at = None if ttl is None else time.time() + ttl
            self.entries[key] = {"value": value, "expires_at": expires_at}
            try:
                self._persist_locked()
            except BaseException:
                self.entries = old_entries
                raise
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            changed = self._prune_locked()
            if changed:
                self._persist_locked()
            entry = self.entries.get(key)
            if entry is None:
                return False, None
            return True, entry["value"]

    def delete(self, key: str) -> bool:
        with self.lock:
            old_entries = self.entries.copy()
            self._prune_locked()
            if key not in self.entries:
                if self.entries != old_entries:
                    self._persist_locked()
                return False
            del self.entries[key]
            try:
                self._persist_locked()
            except BaseException:
                self.entries = old_entries
                raise
            return True

    def keys(self) -> list[str]:
        with self.lock:
            if self._prune_locked():
                self._persist_locked()
            return sorted(self.entries)

    def compact(self) -> None:
        with self.lock:
            if self._prune_locked():
                self._persist_locked()


